// Função para converter datas no formato iCal (YYYYMMDD) para AAAA-MM-DD
function parseICalDate(dateStr) {
  if (!dateStr) return null;
  // Remove hora se houver (ex: 20260810T150000Z -> 20260810)
  const cleanDate = dateStr.split('T')[0];
  if (cleanDate.length >= 8) {
    const ano = cleanDate.substring(0, 4);
    const mes = cleanDate.substring(4, 6);
    const dia = cleanDate.substring(6, 8);
    return `${ano}-${mes}-${dia}`;
  }
  return null;
}

const results = [];

for (const item of $input.all()) {
  const icalText = item.json.data || item.json.body || item.json.text || "";

  // Divide o arquivo iCal em eventos (VEVENT)
  const events = icalText.split('BEGIN:VEVENT');

  for (let i = 1; i < events.length; i++) {
    const event = events[i];

    const summaryMatch = event.match(/SUMMARY:(.*)/);
    const dtstartMatch = event.match(/DTSTART(?:;VALUE=DATE)?:(\d+)/);
    const dtendMatch = event.match(/DTEND(?:;VALUE=DATE)?:(\d+)/);
    const uidMatch = event.match(/UID:(.*)/);

    if (dtstartMatch && dtendMatch) {
      results.push({
        json: {
          idReserva: uidMatch ? uidMatch[1].trim() : `ical-${Date.now()}-${i}`,
          summary: summaryMatch ? summaryMatch[1].trim() : "Bloqueio iCal",
          checkIn: parseICalDate(dtstartMatch[1]),
          checkOut: parseICalDate(dtendMatch[1]),
          plataforma: summaryMatch && summaryMatch[1].includes("Airbnb") ? "Airbnb" : "iCal / Outro"
        }
      });
    }
  }
}

return results.slice(0, 5);

function parseDateUTC(dateStr) {
  if (!dateStr) return null;
  const cleanStr = String(dateStr).substring(0, 10);
  const [year, month, day] = cleanStr.split('-').map(Number);
  return new Date(Date.UTC(year, month - 1, day));
}

// formata data pt-BR (ex: "22 de agosto")
function dataBonita(d) {
  if (!d) return "";
  const meses = ["janeiro","fevereiro","março","abril","maio","junho","julho","agosto","setembro","outubro","novembro","dezembro"];
  return `${d.getUTCDate()} de ${meses[d.getUTCMonth()]}`;
}

const now = new Date();
const today = new Date(Date.UTC(now.getFullYear(), now.getMonth(), now.getDate()));

for (const item of $input.all()) {
  const fields = item.json.fields || item.json;

  // 🛑 TRAVA DE SEGURANÇA: Se a reserva estiver cancelada, ignora
  if (fields['Status da Reserva'] === 'Cancelada') {
    continue;
  }

  if (!fields['Check-in'] || !fields['Check-out']) {
    continue;
  }

  const checkIn = parseDateUTC(fields['Check-in']);
  const checkOut = parseDateUTC(fields['Check-out']);

  const diffCheckInDays = Math.round((checkIn - today) / (1000 * 60 * 60 * 24));
  const diffCheckOutDays = Math.round((checkOut - today) / (1000 * 60 * 60 * 24));

  item.json.diasParaCheckIn = diffCheckInDays;
  item.json.diasParaCheckOut = diffCheckOutDays;

  // datas formatadas bonitinho
  item.json.checkInFormatado = dataBonita(checkIn);
  item.json.checkOutFormatado = dataBonita(checkOut);

  let msgType = null;
  let checkboxField = null;

  // REGRAS DAS MENSAGENS:
  if (diffCheckInDays === 5 && !fields['5 dias antes (msg check-in)']) {
    msgType = '5_DIAS';
    checkboxField = '5 dias antes (msg check-in)';
  } else if (diffCheckInDays === 1 && !fields['1 dia antes (msg check-in)']) {
    msgType = '1_DIA';
    checkboxField = '1 dia antes (msg check-in)';
  } else if (diffCheckInDays === 0 && !fields['Boas Vindas (msg no dia)']) {
    msgType = 'BOAS_VINDAS';
    checkboxField = 'Boas Vindas (msg no dia)';
  } else if (diffCheckOutDays === 1 && !fields['Aviso Faxina (1 dia antes)']) {
    msgType = 'FAXINA_1_DIA';
    checkboxField = 'Aviso Faxina (1 dia antes)';
  } else if (diffCheckOutDays === 0 && !fields['No dia (msg check-out)']) {
    msgType = 'CHECKOUT';
    checkboxField = 'No dia (msg check-out)';
  }

  item.json.msgType = msgType;
  item.json.checkboxField = checkboxField;
}

return $input.all().filter(item => item.json.msgType !== null);

